import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int total = Integer.parseInt(st.nextToken());
        int max_select = Integer.parseInt(st.nextToken());

        double[] probs = new double[total];
        int[] position = new int[total];
        Arrays.fill(position, -1);
        int valid_count = 0;

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < total; i++) {
            probs[i] = Double.parseDouble(st.nextToken());
            if (probs[i] > 1e-9) {
                position[i] = valid_count++;
            }
        }

        max_select = Math.min(max_select, valid_count);

        int size = 1 << valid_count;
        double[] D = new double[size];
        double[] sum_probs = new double[size];
        double[] answer = new double[valid_count];

        D[0] = 1.0;

        for (int mask = 1; mask < size; mask++) {
            int last_bit = Integer.numberOfTrailingZeros(mask);
            int prev_mask = mask ^ (1 << last_bit);
            sum_probs[mask] = sum_probs[prev_mask] + probs[last_bit];
            for (int i = 0; i < valid_count; i++) {
                if (((mask >> i) & 1) == 1) continue;
                if (1.0 - sum_probs[mask] != 0) {
                    D[mask | (1 << i)] += D[mask] * probs[i] / (1.0 - sum_probs[mask]);
                }
            }
        }

        for (int mask = 0; mask < size; mask++) {
            int count_bits = Integer.bitCount(mask);
            if (count_bits == max_select) {
                for (int i = 0; i < valid_count; i++) {
                    if (((mask >> i) & 1) == 1) {
                        answer[i] += D[mask];
                    }
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < total; i++) {
            if (position[i] == -1) {
                sb.append("0 ");
            } else {
                sb.append(answer[position[i]]).append(" ");
            }
        }
        System.out.println(sb.toString().trim());
    }
}
